INSERT INTO public.events (id,user_id,title,visibility,created_at,updated_at,deleted_at,long_description,short_description) VALUES ('4005ad0a-82c8-5071-9f76-804e753738a7', NULL, 'Solemnity of Mary, Mother of God', 'system', DEFAULT, DEFAULT, '2020-11-03T10:12:43.000Z', 'Observed on January 1st, this [Holy Day of Obligation](https://www.xavier.edu) honors the Blessed Virgin Mary as the ''Theotokos'' (God-bearer).', 'A celebration of Mary''s motherhood of Jesus.'), ('87f19d2c-6490-5bfc-b551-bacabbea7ab3', NULL, 'Epiphany of the Lord', 'system', DEFAULT, DEFAULT, '2020-06-26T05:28:37.000Z', 'Celebrates the [manifestation of the divine nature of Jesus](https://library.framingham.edu) to the Magi, signifying that the savior has come for all nations.', 'Commemorates the revelation of Christ to the world.'), ('ee6511da-c2f8-569e-ac7e-8c323a022ac3', NULL, 'Feast of the Transfiguration', 'system', DEFAULT, DEFAULT, '2020-09-25T20:56:25.000Z', 'Recalls the event where [Jesus’ physical appearance became brilliant](https://laverne.edu) as He spoke with Moses and Elijah, revealing His divine glory.', 'Commemorates Jesus'' radiant appearance on Mount Tabor.'), ('1673bb82-e1a3-57a0-9e40-2ba1a6518133', NULL, 'Feast of the Assumption', 'system', DEFAULT, DEFAULT, '2020-07-03T18:25:44.000Z', 'A [Catholic solemnity](https://www.xavier.edu) on August 15th observing the Blessed Virgin Mary''s assumption into heavenly glory.', 'Celebrates Mary being taken body and soul into heaven.'), ('77a23d72-77dc-5dec-a06d-22ea5e1da368', NULL, 'The Exaltation of the Holy Cross', 'system', DEFAULT, DEFAULT, '2020-01-09T12:00:43.000Z', 'Commemorates the finding and [annual elevation of the cross](https://buildfaith.org) used in the crucifixion of Jesus Christ.', 'Also known as Holy Rood Day, honoring the Cross of Christ.'), ('39c387a6-be78-5de9-afec-e80f0a08bd25', NULL, 'Reformation Day', 'system', DEFAULT, DEFAULT, '2020-08-12T19:56:29.000Z', 'Observed on October 31st, marking the anniversary of [Martin Luther nailing the 95 Theses](https://www.faithward.org) to the church door in Wittenberg.', 'Commemorates the start of the Protestant Reformation.'), ('9ae6a42f-4596-5693-85fd-af4b532ff143', NULL, 'All Saints'' Day', 'system', DEFAULT, DEFAULT, '2020-11-03T10:23:20.000Z', 'A day to honor all those who have achieved [lives of holiness](https://libguides.asu.edu) or were martyred for their faith. Also referred to as Solemnity of All Saints.', 'Honoring all saints, known and unknown.'), ('31bf359f-c31c-5f61-9c9a-4ae7b52d32e8', NULL, 'Feast of the Immaculate Conception', 'system', DEFAULT, DEFAULT, '2020-12-20T12:01:32.000Z', 'A [Holy Day of Obligation](https://www.bbcatholic.org.au) on December 8th, celebrating the belief that Mary was preserved from original sin from her conception.', 'Celebrates Mary being conceived without original sin.');
INSERT INTO public.event_date_rules (id,event_id,rule_type,algorithm,frequency,operations,calendar_type,relative_event_id,month,day,weekday,week_of_month,interval,created_at,updated_at) VALUES ('06ab91a1-7404-50c6-ac7b-6bad46ed8e41', '4005ad0a-82c8-5071-9f76-804e753738a7', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 0, 1, NULL, NULL, NULL, DEFAULT, DEFAULT), ('0a7c8c9c-0882-5f0b-93f5-1a4753247f65', '87f19d2c-6490-5bfc-b551-bacabbea7ab3', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 0, 6, NULL, NULL, NULL, DEFAULT, DEFAULT), ('efdefccd-f14c-57c9-bd8b-acc421317d9a', 'ee6511da-c2f8-569e-ac7e-8c323a022ac3', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 7, 6, NULL, NULL, NULL, DEFAULT, DEFAULT), ('1071e742-65cd-511c-9923-da27ad7e62be', '1673bb82-e1a3-57a0-9e40-2ba1a6518133', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 7, 15, NULL, NULL, NULL, DEFAULT, DEFAULT), ('b85853b8-59ad-5a67-b261-33f562796fe9', '77a23d72-77dc-5dec-a06d-22ea5e1da368', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 8, 14, NULL, NULL, NULL, DEFAULT, DEFAULT), ('a3791d54-41fc-5be3-8c5d-79e6d9d2f5c8', '39c387a6-be78-5de9-afec-e80f0a08bd25', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 9, 31, NULL, NULL, NULL, DEFAULT, DEFAULT), ('2a6b2c3f-b84b-5063-8bf7-467ee9d30f6a', '9ae6a42f-4596-5693-85fd-af4b532ff143', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 10, 1, NULL, NULL, NULL, DEFAULT, DEFAULT), ('31790828-85f3-5823-a2b3-2ffe98215dd2', '31bf359f-c31c-5f61-9c9a-4ae7b52d32e8', 'fixed', NULL, 'yearly', '{}', 'gregorian', NULL, 10, 1, NULL, NULL, NULL, DEFAULT, DEFAULT);
INSERT INTO public.events (id,user_id,title,visibility,created_at,updated_at,deleted_at,long_description,short_description) VALUES ('25ea06d1-fd72-5e26-9a4c-7fa5d64a9059', NULL, 'Palm Sunday', 'system', DEFAULT, DEFAULT, '2020-08-16T07:56:05.000Z', 'The [beginning of Holy Week](https://libguides.asu.edu), recalled with the blessing of palm branches to signify the crowds who welcomed Jesus.', 'The commemoration of Jesus'' triumphal entry into Jerusalem.'), ('ba21786d-c45b-5ca3-9cfb-be84658aba5a', NULL, 'Easter', 'system', DEFAULT, DEFAULT, '2020-09-05T08:41:52.000Z', 'The [holiest period of the Church year](https://seaportshrine.org), including the Easter Vigil—the first liturgical celebration of the Resurrection—and Easter Sunday.', 'The celebration of the Passion, Death, and Resurrection of Jesus.'), ('b60b18b1-c68c-518c-a65f-76474cb7c775', NULL, 'Feast of the Ascension', 'system', DEFAULT, DEFAULT, '2020-02-02T13:34:07.000Z', 'Occurring 40 days after the Resurrection, this feast marks the moment [Jesus ascended bodily into heaven](https://www.christianity.com) in the presence of His apostles.', 'Celebrates Jesus Christ ascending into heaven.'), ('48b95ef3-7216-557e-b0a6-932d42ee0f3e', NULL, 'Pentecost', 'system', DEFAULT, DEFAULT, '2020-03-07T14:28:47.000Z', 'Celebrated 50 days after Easter, it commemorates the [Holy Spirit coming to the disciples](https://libguides.asu.edu) as ''tongues of fire,'' marking the birth of the Church.', 'The descent of the Holy Spirit upon the Apostles.'), ('ea32c3fb-17c3-5145-a33f-3ab3fbf2e699', NULL, 'Christmas', 'system', DEFAULT, DEFAULT, '2020-01-09T12:48:01.000Z', 'A major solemnity celebrating the [birth of Jesus Christ](https://www.vaticannews.va) in Bethlehem. It marks the end of Advent and the start of the Christmas season.', 'The Nativity of Jesus Christ and the beginning of Christmastide.'), ('68d94566-e198-568d-97e7-21e58b50ce36', NULL, 'Feast of Corpus Christi', 'system', DEFAULT, DEFAULT, '2020-05-13T04:51:59.000Z', 'A feast honoring the real presence of the [body and blood of Jesus](https://github.com) in the Eucharist, traditionally celebrated after Trinity Sunday.', 'The Solemnity of the Most Holy Body and Blood of Christ.'), ('e0467b1a-8763-53e5-aa4a-ce15515b5d5e', NULL, 'First Sunday of Advent', 'system', DEFAULT, DEFAULT, '2020-05-25T16:28:38.000Z', 'Marks the start of the [Advent season](https://www.usccb.org worship/liturgical-year/advent), a time of expectant waiting and preparation for both the celebration of the Nativity of Christ at Christmas and the return of Christ at the Second Coming.', 'The beginning of the liturgical year and a season of preparation.'), ('6d77921d-6f9e-5ad8-82db-cfe79760ff07', NULL, 'Solemnity of Christ the King', 'system', DEFAULT, DEFAULT, '2020-05-13T16:29:02.000Z', 'The final Sunday of the [liturgical year](https://www.facebook.com), emphasizing Christ''s sovereignty over the universe.', 'Honors Jesus Christ as Lord of all creation.'), ('372ac1d5-b5a7-5452-876c-d52185168fd2', NULL, 'Totensonntag', 'system', DEFAULT, DEFAULT, '2020-11-27T22:31:18.000Z', 'The last Sunday before Advent in German Lutheran traditions, dedicated to [remembering those who have died](https://www.christianity.com) in the past year.', 'Sunday of the Dead; a German Protestant day of remembrance.');
